// Photo auto-fill with a Workers AI vision model.
// Input format (messages + image_url data URI) and response_format JSON mode are taken from the
// model's type definitions generated by `wrangler types` (Ai_Cf_Meta_Llama_4_Scout_17B_16E_Instruct_*).
// Model page: https://developers.cloudflare.com/workers-ai/models/llama-4-scout-17b-16e-instruct/
import { CATEGORIES, FORMALITIES, SEASONS, normalizeCategory, normalizeFormality, normalizeSeason } from './model';

export const VISION_MODEL = '@cf/meta/llama-4-scout-17b-16e-instruct';
const MAX_IMAGE_BYTES = 4 * 1024 * 1024;

export interface PhotoSuggestion {
  name: string | null;
  category: string | null;
  color: string | null;
  season: string | null;
  formality: string | null;
  brand: string | null;
  style: string | null;
  notes: string | null;
}

const SCHEMA = {
  type: 'object',
  properties: {
    name: { type: 'string', description: 'Short descriptive name, e.g. "Navy wool crewneck sweater"' },
    category: { type: 'string', enum: [...CATEGORIES] },
    color: { type: 'string', description: 'Main color(s), plain words, e.g. "navy" or "white/blue stripe"' },
    season: { type: 'array', items: { type: 'string', enum: [...SEASONS, 'all'] } },
    formality: { type: 'string', enum: [...FORMALITIES] },
    style: { type: 'string', description: 'A few style words: fit, fabric, pattern, details' },
    brand: { type: 'string', description: 'Only if a logo or label is clearly legible, else empty string' },
  },
  required: ['name', 'category', 'color', 'season', 'formality', 'style'],
};

const PROMPT = `You catalog clothing for a personal wardrobe app. Look at the single main garment, shoe or accessory in the photo and describe it.
Rules:
- category: one of ${CATEGORIES.join(', ')}.
- formality: casual (everyday, athletic, denim, tees), business (office: chinos, button-downs, blazers, loafers), formal (suits, gowns, tuxedo, dress shoes for events).
- season: the seasons it suits; use ["all"] for year-round basics.
- brand: only if you can actually read it; otherwise "".
Respond with JSON only.`;

function toBase64(buf: ArrayBuffer): string {
  const bytes = new Uint8Array(buf);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(bin);
}

function parseJsonLoose(r: unknown): Record<string, unknown> {
  if (r && typeof r === 'object') return r as Record<string, unknown>;
  const s = String(r ?? '');
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('model did not return JSON');
  return JSON.parse(s.slice(start, end + 1));
}

function safe<T>(fn: () => T): T | null {
  try { return fn(); } catch { return null; }
}

function text(v: unknown, max = 200): string | null {
  const s = typeof v === 'string' ? v.trim() : '';
  return s ? s.slice(0, max) : null;
}

export async function analyzePhoto(ai: Ai, image: ArrayBuffer, contentType: string): Promise<PhotoSuggestion> {
  if (image.byteLength > MAX_IMAGE_BYTES) throw new Error('image too large for analysis (max 4 MB)');
  const dataUri = `data:${contentType || 'image/jpeg'};base64,${toBase64(image)}`;

  const out = await ai.run(VISION_MODEL, {
    messages: [
      { role: 'system', content: PROMPT },
      {
        role: 'user',
        content: [
          { type: 'text', text: 'Describe this item.' },
          { type: 'image_url', image_url: { url: dataUri } },
        ],
      },
    ],
    response_format: { type: 'json_schema', json_schema: SCHEMA },
    max_tokens: 400,
    temperature: 0.2,
  });

  const raw = parseJsonLoose((out as { response?: unknown }).response);
  const style = text(raw.style, 300);
  return {
    name: text(raw.name),
    category: safe(() => normalizeCategory(raw.category)),
    color: text(raw.color, 100),
    season: safe(() => normalizeSeason(raw.season)),
    formality: safe(() => normalizeFormality(raw.formality)),
    brand: text(raw.brand, 100),
    style,
    notes: style,
  };
}
